CREATE TYPE "ClinicalAppointmentStatus" AS ENUM ('SCHEDULED','ATTENDED','CANCELLED','ABSENT');
CREATE TABLE "clinical_patients" ("person_id" UUID NOT NULL,"registered_by_id" UUID NOT NULL,"registered_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "clinical_patients_pkey" PRIMARY KEY ("person_id"));
CREATE TABLE "clinical_appointments" ("id" UUID NOT NULL,"person_id" UUID NOT NULL,"professional_id" UUID NOT NULL,"start_at" TIMESTAMPTZ(6) NOT NULL,"duration_minutes" INTEGER NOT NULL DEFAULT 60,"status" "ClinicalAppointmentStatus" NOT NULL DEFAULT 'SCHEDULED',"operational_note" TEXT,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "clinical_appointments_pkey" PRIMARY KEY ("id"),CONSTRAINT "clinical_appointments_duration_check" CHECK ("duration_minutes" > 0));
CREATE INDEX "clinical_appointments_person_idx" ON "clinical_appointments"("person_id","start_at"); CREATE INDEX "clinical_appointments_professional_idx" ON "clinical_appointments"("professional_id","start_at"); CREATE INDEX "clinical_appointments_status_idx" ON "clinical_appointments"("status","start_at");
ALTER TABLE "clinical_patients" ADD CONSTRAINT "clinical_patients_person_fkey" FOREIGN KEY ("person_id") REFERENCES "people"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "clinical_patients" ADD CONSTRAINT "clinical_patients_user_fkey" FOREIGN KEY ("registered_by_id") REFERENCES "internal_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "clinical_appointments" ADD CONSTRAINT "clinical_appointments_person_fkey" FOREIGN KEY ("person_id") REFERENCES "people"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "clinical_appointments" ADD CONSTRAINT "clinical_appointments_prof_fkey" FOREIGN KEY ("professional_id") REFERENCES "internal_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
